  async function submitMasterApply() {
    if (!cloud || !state.user) { toast('请先登录后再提交申请', true); openLogin(); return; }
    var name = (document.getElementById('tApplyName').value || '').trim();
    var contact = (document.getElementById('tApplyContact').value || '').trim();
    var years = document.getElementById('tApplyYears').value;
    var focus = document.getElementById('tApplyFocus').value;
    var bio = (document.getElementById('tApplyBio').value || '').trim();
    if (!name) { toast('请填写称呼', true); return; }
    if (!contact) { toast('请填写联系方式', true); return; }
    if (!/^[\w\-]{4,30}$/.test(contact) && !/^1\d{10}$/.test(contact)) {
      toast('联系方式格式不正确（微信号或 11 位手机号）', true);
      return;
    }
    if (bio.length < 10) { toast('个人简介至少填写 10 个字', true); return; }
    var btn = document.getElementById('applySubmitBtn');
    if (btn) { btn.disabled = true; btn.textContent = '提交中…'; }
    try {
      await cloud.database.from('master_applications').insert({
        owner_name: state.user.name || null,
        name: name,
        contact: contact,
        years: years,
        focus: focus,
        bio: bio,
        status: 'pending'
      });
      toast('申请已提交，平台将在 3 个工作日内完成审核');
      document.getElementById('tApplyName').value = '';
      document.getElementById('tApplyContact').value = '';
      document.getElementById('tApplyBio').value = '';
    } catch (e) {
      toast('提交失败，请稍后重试', true);
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = '提交申请'; }
    }
  }

